challenge.solution:
가로 = 0
세로 = 0
명령 = input("명령: ")
for 글자 in 명령:
    if 글자 == "R":
        가로 += 1
    elif 글자 == "L":
        가로 -= 1
    elif 글자 == "U":
        세로 += 1
    elif 글자 == "D":
        세로 -= 1
print(가로, 세로)
